import{_ as t,o as a,c as n,a0 as s}from"./chunks/framework.DVUHX04-.js";const m=JSON.parse('{"title":"Gist names percent-encode sync paths, and empty files are absent","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0010-gist-names-encode-paths-empty-files-absent.md","filePath":"adr/0010-gist-names-encode-paths-empty-files-absent.md","lastUpdated":1789477531000}'),o={name:"adr/0010-gist-names-encode-paths-empty-files-absent.md"};function i(d,e,r,c,p,l){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="gist-names-percent-encode-sync-paths-and-empty-files-are-absent" tabindex="-1">Gist names percent-encode sync paths, and empty files are absent <a class="header-anchor" href="#gist-names-percent-encode-sync-paths-and-empty-files-are-absent" aria-label="Permalink to &quot;Gist names percent-encode sync paths, and empty files are absent&quot;">​</a></h1><p>GitHub gists are flat and text-only: a file name cannot contain <code>/</code>, and a file cannot hold empty content (create fails with HTTP 422; on update, GitHub deletes a file set to <code>&quot;&quot;</code>). The Gist Backend therefore stores each home-relative path under its percent-encoded name, leaving only <code>[A-Za-z0-9._-]</code> literal, so <code>.pi/agent/settings.json</code> travels as <code>.pi%2Fagent%2Fsettings.json</code>. The mapping is one-to-one and decoded on fetch, so paths survive the round trip while root files like <code>AGENTS.md</code> stay human-readable in the GitHub UI. Zero-byte files are skipped at collection time with a warning and are absent from the Snapshot: an empty file has nothing to carry, and truncating a file to empty reads as a deletion in the three-way merge.</p><p>Considered options: a delimiter token for <code>/</code> (collides with real names, not reversible); a path-to-name mapping stored in the manifest (fetch must derive the path from the name alone, before any config is trusted); a placeholder for empty content (breaks the content hash and shows up in the GitHub UI).</p>',3)])])}const f=t(o,[["render",i]]);export{m as __pageData,f as default};
